import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts (assume single relevant value)
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Filter out already-applied events (event_ts <= high_ts)
    if high_ts is not None:
        cdc_pending = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        cdc_pending = cdc_events.copy()

    # Sort events per (event_ts, event_seq) for sequential application
    cdc_pending = cdc_pending.sort_values(["event_ts", "event_seq"], kind="mergesort")

    # Build initial state from target_snapshot
    states = {}
    for _, row in target_snapshot.iterrows():
        states[row["item_id"]] = {
            "qty": row["qty_on_hand"],
            "last_ts": row["last_event_ts"],
            "exists": True,
        }

    # Apply events sequentially
    for _, ev in cdc_pending.iterrows():
        item = ev["item_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        qty = ev["qty"]

        state = states.get(item)
        if state is None:
            state = {"qty": None, "last_ts": None, "exists": False}
            states[item] = state

        if op == "D":
            state["exists"] = False
            state["qty"] = None
            state["last_ts"] = ts
        elif op == "R":
            if state["exists"]:
                state["qty"] = state["qty"] + qty
            else:
                state["qty"] = 0 + qty
                state["exists"] = True
            state["last_ts"] = ts
        elif op == "A":
            state["qty"] = qty
            state["exists"] = True
            state["last_ts"] = ts
        # unknown ops are ignored (not expected per spec)

    # Build final output: only existing items
    records = []
    for item_id, state in states.items():
        if state["exists"]:
            records.append(
                {
                    "item_id": item_id,
                    "qty_on_hand": state["qty"],
                    "last_event_ts": state["last_ts"],
                }
            )

    new_snapshot = pd.DataFrame(
        records, columns=["item_id", "qty_on_hand", "last_event_ts"]
    )

    # Align dtypes with target_snapshot where possible
    if not target_snapshot.empty:
        try:
            new_snapshot["item_id"] = new_snapshot["item_id"].astype(
                target_snapshot["item_id"].dtype
            )
        except Exception:
            pass
        try:
            new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype(
                target_snapshot["qty_on_hand"].dtype
            )
        except Exception:
            pass
        try:
            new_snapshot["last_event_ts"] = pd.to_datetime(
                new_snapshot["last_event_ts"]
            )
        except Exception:
            pass

    return {"new_snapshot": new_snapshot}
